            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Avoid floating point to preserve precision
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a * b) < 0 else 1
                res = abs(a) // abs(b)
